#[test]
fn test_len_gcode(){
    println!("len: {}",TEST_GCODE.len());
    println!("lines: {}",TEST_GCODE.split('\n').count());
    println!("layers: {}",TEST_GCODE.split(";LAYER_CHANGE").count());

    println!("lines: {}",
        // (TEST_GCODE.split('\n').count() as f64) / (TEST_GCODE.len() as f64)
         (TEST_GCODE.len() as f64) / (TEST_GCODE.split('\n').count() as f64)
    );
    println!("lines: {}",
        // (TEST_GCODE.split(";LAYER_CHANGE").count() as f64) / (TEST_GCODE.len() as f64)
         (TEST_GCODE.len() as f64) / (TEST_GCODE.split(";LAYER_CHANGE").count() as f64)
    );
    assert!(false)
}

